import sys

def find_smallest_n(x):
    if x == 1:
        return 1
    n = 1
    while True:
        max_ones = 0
        if n % 2 == 1:
            center = n // 2
            max_ones += (center + 1) ** 2
        else:
            center = n // 2
            max_ones += center * (center + 1)
        if max_ones >= x:
            break
        n += 1
    return n

x = int(sys.stdin.read().strip())
print(find_smallest_n(x))
